export const DRAFT_CATALOGS = Object.freeze(Object.fromEntries(LOCALES.map((locale,index)=>[locale,Object.freeze(Object.fromEntries(rows.map(([key,...values])=>[key,values[index]])))])));

const aliases=Object.freeze({en:'en','zh-hant':'zh-Hant','zh-tw':'zh-Hant','zh-hans':'zh-Hans','zh-cn':'zh-Hans',ja:'ja',ko:'ko',es:'es',pt:'pt-BR','pt-br':'pt-BR',fr:'fr',de:'de',it:'it',ru:'ru',hi:'hi',ar:'ar'});
export function resolveLocale(options={}) {
  const pathname=options.pathname ?? globalThis.location?.pathname ?? '';
  const parts=String(pathname).split('/').filter(Boolean);
  if(parts[0]==='weightplay')parts.shift();
  if(aliases[parts[0]?.toLowerCase()])return aliases[parts[0].toLowerCase()];
  try {const query=new URLSearchParams(options.search ?? globalThis.location?.search ?? '');const candidate=(query.get('lang')||query.get('locale')||'').toLowerCase();if(aliases[candidate])return aliases[candidate];}catch{}
  try {const referrer=Object.hasOwn(options,'referrer')?options.referrer:Object.keys(options).length===0?globalThis.document?.referrer:'';const url=new URL(referrer);if(url.origin===globalThis.location?.origin){const segment=url.pathname.split('/').filter(Boolean)[0]?.toLowerCase();if(aliases[segment])return aliases[segment];}}catch{}
  try {const storage=Object.hasOwn(options,'storage')?options.storage:globalThis.localStorage;const stored=(storage?.getItem('weightPlayLocale')||'').toLowerCase();if(aliases[stored])return aliases[stored];}catch{}
  return aliases[String(options.documentLanguage ?? globalThis.document?.documentElement?.lang ?? 'en').toLowerCase()]||'en';
}
export function translate(locale,key,variables={}) {
  const entry=DRAFT_CATALOGS[locale]?.[key];
  if(typeof entry!=='string')throw new Error(`MISSING_STRIDE_TRANSLATION: ${locale}/${key}`);
  return entry.replace(/\{(\w+)\}/g,(whole,name)=>Object.hasOwn(variables,name)?String(variables[name]):whole);
}

export const ROUTE_SEGMENTS=Object.freeze({en:'en','zh-Hant':'zh-tw','zh-Hans':'zh-cn',ja:'ja',ko:'ko',es:'es','pt-BR':'pt-br',fr:'fr',de:'de',it:'it',ru:'ru',hi:'hi',ar:'ar'});
const escapeHtml=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const attribute=(tag,name)=>tag.match(new RegExp(`(?:^|\\s)${name}\\s*=\\s*(["'])(.*?)\\1`,'i'))?.[2];
const setAttribute=(tag,name,value)=>{
  const pattern=new RegExp(`\\s${name}\\s*=\\s*(["'])[\\s\\S]*?\\1`,'i');
  return pattern.test(tag)?tag.replace(pattern,` ${name}="${escapeHtml(value)}"`):tag.replace(/>$/,` ${name}="${escapeHtml(value)}">`);
};
export function guideExtras(locale){
  const faq=['Shoes','Trail','Save'].map(x=>({question:translate(locale,`faq${x}Q`),answer:translate(locale,`faq${x}A`)}));
  const faqHtml=`<h3>${escapeHtml(translate(locale,'faqTitle'))}</h3>`+faq.map(x=>`<details><summary>${escapeHtml(x.question)}</summary><p>${escapeHtml(x.answer)}</p></details>`).join('');
  const cards=RELATED_GAMES.map(g=>`<a class="game-info-related-card" data-game-id="${g.id}" href="/${ROUTE_SEGMENTS[locale]}/games/${g.id}/"><span class="game-info-related-poster"><img src="${g.poster}" alt="${escapeHtml(g.titles[locale])}" loading="lazy" width="320" height="320"></span><span class="game-info-related-copy"><strong data-runtime-localize="off">${escapeHtml(g.titles[locale])}</strong></span></a>`).join('');
  return {faq,faqHtml,relatedHtml:`<h3>${escapeHtml(translate(locale,'relatedTitle'))}</h3><section class="game-info-related-grid">${cards}</section>`};
}
/** Pure first-response rendering; the canonical route writer owns output files. */
export function renderLocalizedRoute(source,locale,titles){
  if(!LOCALES.includes(locale)||typeof source!=='string'||!source.includes('data-game-id="lantern-stride"'))throw new Error('STRIDE_ROUTE_SOURCE_INVALID');
  for(const code of LOCALES)if(typeof titles?.[code]!=='string'||!titles[code].trim())throw new Error(`STRIDE_TITLE_MISSING: ${code}`);
  const segment=ROUTE_SEGMENTS[locale], title=titles[locale].trim(), pageTitle=`${title} | WeightPlay`;
  const url=`https://weightplay.com/${segment}/games/lantern-stride/`,description=translate(locale,'summary'), extras=guideExtras(locale);
  const robots=attribute(source.match(/<meta\b[^>]*\bname=["']robots["'][^>]*>/i)?.[0]||'','content')||'noindex,nofollow';
  let html=source.replace(/<html\b[^>]*>/i,tag=>setAttribute(setAttribute(tag,'lang',locale),'dir',locale==='ar'?'rtl':'ltr'));
  html=html.replace(/(<([a-z][\w-]*)\b[^>]*\bdata-t=["']([^"']+)["'][^>]*>)([^<]*)(<\/\2\s*>)/gi,(_all,open,_tag,key,_old,close)=>`${open}${escapeHtml(translate(locale,key))}${close}`);
  html=html.replace(/<[a-z][\w-]*\b[^>]*\bdata-t-aria=["'][^"']+["'][^>]*>/gi,tag=>setAttribute(tag,'aria-label',translate(locale,attribute(tag,'data-t-aria'))));
  html=html.replace(/<img\b[^>]*\bdata-t-alt=["'][^"']+["'][^>]*>/gi,tag=>setAttribute(tag,'alt',translate(locale,attribute(tag,'data-t-alt'))));
  html=html.replace(/(<([a-z][\w-]*)\b[^>]*\bdata-wp-game-title(?=[\s=>])[^>]*>)[\s\S]*?(<\/\2\s*>)/gi,(_all,open,_tag,close)=>`${open}${escapeHtml(title)}${close}`);
  html=html.replace(/(<p\b[^>]*\bid=["']mainProgress["'][^>]*>)[\s\S]*?(<\/p>)/i,(_all,open,close)=>`${open}${escapeHtml(translate(locale,'stage',{n:'1 / 60'}))}${close}`);
  html=html.replace(/<section\b(?=[^>]*\bid=["']gameGuide["'])[^>]*>/i,tag=>setAttribute(setAttribute(tag,'data-wp-guide-locale',locale),'aria-label',translate(locale,'guideTitle')));
  html=html.replace(/(<div\b[^>]*\bid=["']gameGuideFaq["'][^>]*>)[\s\S]*?(<\/div>)/i,(_all,open,close)=>`${open}${extras.faqHtml}${close}`);
  html=html.replace(/(<div\b[^>]*\bid=["']gameGuideRelated["'][^>]*>)[\s\S]*?(<\/div>)/i,(_all,open,close)=>`${open}${extras.relatedHtml}${close}`);
  html=html.replace(/<a\b(?=[^>]*\bdata-wp-return=["']main["'])[^>]*>/i,tag=>setAttribute(tag,'href',`/${segment}/`));
  html=html.replace(/<title\b[^>]*>[\s\S]*?<\/title>/gi,'').replace(/<meta\b(?=[^>]*\bname=["'](?:description|robots)["'])[^>]*>/gi,'');
  const alternates=LOCALES.map(code=>`<link rel="alternate" hreflang="${code}" href="https://weightplay.com/${ROUTE_SEGMENTS[code]}/games/lantern-stride/">`).join('\n');
  const graph={'@context':'https://schema.org','@type':'VideoGame',name:title,description,url,inLanguage:locale,gamePlatform:'Web browser',applicationCategory:'GameApplication',isAccessibleForFree:true,image:'https://weightplay.com/games/lantern-stride/assets/cover.webp'};
  const metadata=`<base href="/games/lantern-stride/"><title>${escapeHtml(pageTitle)}</title><meta name="description" content="${escapeHtml(description)}"><meta name="robots" content="${escapeHtml(robots)}"><link rel="canonical" href="${url}">${alternates}<link rel="alternate" hreflang="x-default" href="https://weightplay.com/games/lantern-stride/"><meta property="og:title" content="${escapeHtml(pageTitle)}"><meta property="og:description" content="${escapeHtml(description)}"><meta property="og:url" content="${url}"><meta property="og:image" content="https://weightplay.com/games/lantern-stride/assets/cover.webp"><script type="application/ld+json">${JSON.stringify(graph).replaceAll('<','\\u003c')}</script>`;
  if(!/<\/head>/i.test(html))throw new Error('STRIDE_ROUTE_HEAD_MISSING');
  return html.replace(/<\/head>/i,`${metadata}</head>`);
}

